import Link from "next/link";import {Footer} from "@/components/Footer";import {Header} from "@/components/Header";import {VehicleCard} from "@/components/VehicleCard";import {getDealer,getVehicles} from "@/lib/api";
export default async function Inventory({searchParams}:{searchParams:Promise<Record<string,string|undefined>>}){const p=await searchParams;const query=new URLSearchParams();for(const [k,v] of Object.entries(p))if(v)query.set(k,v);const [dealer,vehicles]=await Promise.all([getDealer(),getVehicles(query.toString())]);return <><Header dealer={dealer}/><main id="main" style={{"--brand":dealer.primary_color} as React.CSSProperties}><section className="inventoryHero"><div><span className="eyebrow">Current collection · {String(vehicles.length).padStart(2,"0")}</span><h1>Find your<br/><span className="accentWord">next chapter.</span></h1></div><p>Search a focused collection of distinctive pre-owned vehicles. Every detail shown is dealer-provided and open to conversation.</p></section><form className="filterBar"><label className="searchField"><span>Search collection</span><input type="search" name="q" defaultValue={p.q} placeholder="Make, model or keyword"/></label><label><span>Availability</span><select name="availability" defaultValue={p.availability}><option value="">All vehicles</option><option value="available">Available now</option><option value="reserved">Reserved</option><option value="sold">Sold archive</option></select></label><label><span>Order by</span><select name="sort" defaultValue={p.sort}><option value="newest">Latest arrivals</option><option value="price_low">Price · low first</option><option value="price_high">Price · high first</option></select></label><button className="filterSubmit" aria-label="Apply filters">Apply <span>→</span></button></form><section className="inventorySection">{vehicles.length?<div className="inventoryGrid">{vehicles.map((v,i)=><VehicleCard key={v.id} vehicle={v} index={i}/>)}</div>:<div className="empty"><span className="eyebrow">No match</span><h2>Nothing here—yet.</h2><p>Adjust the filters or tell us what you are looking for.</p><Link className="lineLink" href="/inventory">Reset collection</Link></div>}</section></main><Footer dealer={dealer}/></>}
